import glob
import json
import sys

runs = sys.argv[1]
traces = sys.argv[2]
for line in open(runs):
    r = json.loads(line)
    p = r.get("platform") or {}
    if p.get("quality") is not None and str(r.get("version", "")).startswith("v2"):
        print(r["id"], r.get("experiment"), p.get("quality"), p.get("cost_usd"), r.get("duration_s"),
              r.get("requests"), p.get("scored_duration_s"))
for f in sorted(glob.glob(traces + "/**/*.jsonl", recursive=True)):
    tot = {"requests": 0, "input_tokens": 0, "cached_tokens": 0, "output_tokens": 0}
    kinds = {}
    for line in open(f):
        try:
            e = json.loads(line)
        except ValueError:
            continue
        if "input_tokens" in e:
            kinds[e.get("kind")] = kinds.get(e.get("kind"), 0) + 1
            for k in tot:
                tot[k] += e.get(k) or 0
    print(f.rsplit("/", 2)[-2:], tot, kinds)

